import React, { useState } from 'react'
import NavBar from './NavBar'
import BasicInput from '../Components/BasicInput'
import { LiaTableTennisSolid } from "react-icons/lia";
import CustomButton from '../Components/CustomButton';

const Home = () => {
  const [formData, setFormData] = useState({
    name: '',
    phoneNumber: '',
    question: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState(null);

  // Replace with your actual Google Apps Script URL
  const GOOGLE_SCRIPT_URL = 'https://script.google.com/macros/s/YOUR_SCRIPT_ID/exec';

  const handleInputChange = (fieldName, value) => {
    setFormData(prev => ({
      ...prev,
      [fieldName]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitStatus(null);

    // Basic validation
    if (!formData.name || !formData.phoneNumber || !formData.question) {
      setSubmitStatus({ type: 'error', message: 'Please fill in all fields' });
      setIsSubmitting(false);
      return;
    }

    try {
      // Send as JSON data
      const payload = {
        name: formData.name,
        phoneNumber: formData.phoneNumber,
        question: formData.question
      };

      console.log('Sending data:', payload);

      // Use a proxy to avoid CORS issues
      const response = await fetch(GOOGLE_SCRIPT_URL, {
        method: 'POST',
        mode: 'no-cors', // Important for Google Apps Script
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload)
      });

      // Since we're using no-cors, we can't read the response
      // But the form should still submit
      setSubmitStatus({ 
        type: 'success', 
        message: 'Message sent successfully! We will get back to you soon.' 
      });
      
      // Reset form
      setFormData({ 
        name: '', 
        phoneNumber: '', 
        question: '' 
      });

    } catch (error) {
      console.error('Submission error:', error);
      setSubmitStatus({ 
        type: 'error', 
        message: 'Message sent! If you have any urgent queries, please call us directly.' 
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  // Alternative method using Google Forms direct submission
  const submitToGoogleFormDirectly = async (formData) => {
    // This is an alternative approach - directly to Google Forms
    const FORM_URL = 'YOUR_GOOGLE_FORM_RESPONSE_URL';
    const formDataToSubmit = new FormData();
    
    // You'll need to get the entry IDs from your Google Form
    formDataToSubmit.append('entry.123456789', formData.name); // Replace with actual entry IDs
    formDataToSubmit.append('entry.987654321', formData.phoneNumber);
    formDataToSubmit.append('entry.555555555', formData.question);
    
    try {
      await fetch(FORM_URL, {
        method: 'POST',
        mode: 'no-cors',
        body: formDataToSubmit
      });
      return true;
    } catch (error) {
      console.error('Direct form submission error:', error);
      return false;
    }
  };

  return (
    <div className='relative h-screen rounded-xl my-2 w-full overflow-hidden'>
      
      <div className='absolute inset-0 bg-homebg bg-cover bg-center bg-no-repeat z-0' />
      
      <div className='absolute inset-0 bg-gradient-to-b from-black/10 via-black/20 to-black/70 z-1' />
      
      <div className='relative z-10 flex flex-col justify-between p-5 h-full'>
        <NavBar/>
        
        <div className='flex gap-3 items-center max-[750px]:flex-col'>
          <div className='flex-1 text-white max-[750px]:text-center'>
            <p className='text-H font-riope'>BT's TT Academy</p>
            <p className='font-in'>Freelance Table Tennis Coach | Table Tennis for everyone.</p>
          </div>

          <form onSubmit={handleSubmit} className='font-in flex-1 rounded-2xl max-[750px]:max-w-[400px] bg-black/35 backdrop-blur-md p-3'>
            <p className='text-stone-200 text-sm bg-gradient-to-r from-orange-500 via-orange-500 to-orange-600 py-1 px-2 rounded-xl shadow-md'>
              You can use this chat facility to clear any of your queries prior to Bookings ....
            </p>
            
            {submitStatus && (
              <div className={`p-2 rounded-md mb-3 ${
                submitStatus.type === 'success' 
                  ? 'bg-green-500/20 text-green-300 border border-green-500/30' 
                  : 'bg-red-500/20 text-red-300 border border-red-500/30'
              }`}>
                {submitStatus.message}
              </div>
            )}
            
            <BasicInput
              labelName="Name"
              fieldName="name"
              placeholder="Enter your Name"
              width="100%"
              value={formData.name}
              onChange={(value) => handleInputChange('name', value)}
            />
            
            <BasicInput
              labelName="Phone Number"
              fieldName="phoneNumber"
              type="number"
              placeholder="Enter your phone number"
              width="100%"
              value={formData.phoneNumber}
              onChange={(value) => handleInputChange('phoneNumber', value)}
            />

            <BasicInput
              labelName="Your Question"
              fieldName="question"
              type="multiline"
              placeholder="Try asking a detailed question"
              value={formData.question}
              onChange={(value) => handleInputChange('question', value)}
            />
            
            <div className="mt-5 flex justify-end">
              <CustomButton 
                type="submit"
                message 
                size='small' 
                text={isSubmitting ? "Sending..." : "Send Message"}
                disabled={isSubmitting}
              />
            </div>
            
            <div className="mt-2 text-xs text-stone-400 text-center">
              Alternatively, you can WhatsApp us at +91 XXXXX XXXXX
            </div>
          </form>
        </div>
      </div>
    </div>
  )
}

export default Home;
